/**
 * The broker's dynamic security (P9-13, ADR-0039, security review S2): every user bound to one
 * client id, wrong passwords and anonymous clients refused, the configuration
 * generated by `entrypoint.sh` (fail closed), and ACL parity: every allowed and refused
 * (user, topic, action) of the Phase 8 ACL file behaves the same under the dynamic-security plugin.
 *
 * The parity reference is the Phase 8 broker itself, kept frozen in
 * `packages/test-kit/fixtures/legacy-mosquitto` (its ACL file, password file entrypoint and
 * configuration as of 5629ccf) and run side by side with the project's broker. The table below
 * spells out the expected outcome as well, so a change on both sides still shows up in review.
 */
import { resolve } from 'node:path';
import mqtt, { type IClientOptions, type MqttClient } from 'mqtt';
import type { StartedTestContainer } from 'testcontainers';
import { afterAll, afterEach, beforeAll, describe, expect, it } from 'vitest';
import {
  BOUND_CLIENT_IDS,
  TEST_PASSWORDS,
  brokerLogin,
  mqttUsers,
  startBroker,
  type BrokerUser,
} from './testing.ts';

const LEGACY_CONFIG = resolve(
  import.meta.dirname,
  '../../../packages/test-kit/fixtures/legacy-mosquitto',
);

interface Broker {
  url: string;
  container: StartedTestContainer;
}
let current: Broker;
let legacy: Broker;
const cleanup: (() => Promise<unknown>)[] = [];

const wait = (ms: number) => new Promise((r) => setTimeout(r, ms));

/** A connection, or the reason the broker refused it. */
async function connect(url: string, options: IClientOptions): Promise<MqttClient> {
  const c = await mqtt.connectAsync(url, {
    protocolVersion: 5,
    reconnectPeriod: 0,
    connectTimeout: 5_000,
    ...options,
  });
  cleanup.push(() => c.endAsync(true));
  return c;
}

const refusal = (url: string, options: IClientOptions): Promise<string> =>
  connect(url, options).then(
    () => 'connected',
    (error: unknown) => String(error),
  );

beforeAll(async () => {
  [current, legacy] = await Promise.all([
    startBroker(),
    startBroker({
      configDir: LEGACY_CONFIG,
      mqttUsers: mqttUsers(['healthcheck', 'dev', 'gw-01', 'mes']),
    }),
  ]);
}, 180_000);

afterEach(async () => {
  for (const fn of cleanup.splice(0).reverse()) await fn().catch(() => undefined);
});

afterAll(async () => {
  await Promise.all([current.container.stop(), legacy.container.stop()]);
});

describe('client-id binding (S2)', () => {
  it('binds every user to one client id', () => {
    expect(Object.fromEntries(BOUND_CLIENT_IDS)).toEqual({
      healthcheck: 'healthcheck',
      dev: 'dev',
      'smoke-reader': 'smoke-reader',
      'gw-01': 'gw-01',
      'gw-01-cmd': 'gw-01-cmd',
      mes: 'mes-server',
      'mes-cmd': 'mes-server-cmd',
    });
    expect([...BOUND_CLIENT_IDS.keys()].sort()).toEqual(Object.keys(TEST_PASSWORDS).sort());
  });

  it("refuses every user another user's client id: no session can be taken over", async () => {
    // Mosquitto checks no username on a session takeover (src/handle_connect.c, 2.1.2): a client
    // id is safe only because no user may connect with any id but its own. Every user's session
    // is up (the MES's persistent); every user trying every other user's id is refused, and no
    // session is disconnected.
    const sessions = new Map<string, MqttClient>();
    for (const user of BOUND_CLIENT_IDS.keys()) {
      const login = brokerLogin(user as BrokerUser);
      const options: IClientOptions =
        user === 'mes'
          ? { ...login, clean: false, properties: { sessionExpiryInterval: 600 } }
          : login;
      sessions.set(login.clientId, await connect(current.url, options));
    }
    const kicked: string[] = [];
    for (const [clientId, session] of sessions) {
      session.on('close', () => {
        kicked.push(clientId);
      });
    }
    for (const [user, own] of BOUND_CLIENT_IDS) {
      for (const clientId of BOUND_CLIENT_IDS.values()) {
        if (clientId === own) continue;
        const outcome = await refusal(current.url, {
          username: user,
          password: TEST_PASSWORDS[user as BrokerUser],
          clientId,
        });
        expect(outcome, `${user} as ${clientId}`).toMatch(/Not authorized/);
      }
    }
    await wait(300);
    expect(kicked).toEqual([]);
    expect([...sessions.values()].every((c) => c.connected)).toBe(true);
  });

  it('refuses every user with any other client id, or with a generated one', async () => {
    for (const user of BOUND_CLIENT_IDS.keys()) {
      const password = TEST_PASSWORDS[user as BrokerUser];
      expect(
        await refusal(current.url, { username: user, password, clientId: `${user}-other` }),
        user,
      ).toMatch(/Not authorized/);
      expect(await refusal(current.url, { username: user, password }), user).toMatch(
        /Not authorized/,
      );
    }
  });

  it('lets every user connect with its own client id', async () => {
    for (const user of Object.keys(TEST_PASSWORDS) as BrokerUser[]) {
      expect(await refusal(current.url, brokerLogin(user)), user).toBe('connected');
    }
  });
});

describe('authentication (S2)', () => {
  it('refuses a wrong password, another user’s password and an unknown user', async () => {
    for (const user of Object.keys(TEST_PASSWORDS) as BrokerUser[]) {
      expect(
        await refusal(current.url, { ...brokerLogin(user), password: 'not-the-password' }),
        user,
      ).toMatch(/Not authorized|Bad User Name or Password/);
    }
    expect(
      await refusal(current.url, { ...brokerLogin('gw-01'), password: TEST_PASSWORDS.mes }),
    ).toMatch(/Not authorized|Bad User Name or Password/);
    expect(
      await refusal(current.url, {
        ...brokerLogin('mes'),
        username: 'mes-server',
        password: TEST_PASSWORDS.mes,
      }),
    ).toMatch(/Not authorized|Bad User Name or Password/);
  });

  it('refuses an anonymous client, with or without a bound client id', async () => {
    expect(await refusal(current.url, {})).toMatch(/Not authorized/);
    expect(await refusal(current.url, { clientId: 'mes-server' })).toMatch(/Not authorized/);
    expect(await refusal(current.url, { username: 'dev', clientId: 'dev' })).toMatch(
      /Not authorized|Bad User Name or Password/,
    );
  });
});

describe('configuration generated by entrypoint.sh (fail closed)', () => {
  it('refuses to start when a user of the template gets no password', async () => {
    await expect(
      startBroker({
        mqttUsers: mqttUsers(['dev', 'gw-01', 'gw-01-cmd', 'mes', 'mes-cmd']),
        readyTimeoutMs: 3_000,
      }),
    ).rejects.toThrow(/did not start/);
  });

  it('refuses to start when MQTT_USERS names a user the template does not have', async () => {
    await expect(
      startBroker({ mqttUsers: `${mqttUsers()} intruder:x`, readyTimeoutMs: 3_000 }),
    ).rejects.toThrow(/did not start/);
  });

  it('refuses a user name that is a pattern, not a name (security review F1)', async () => {
    // `d.v` matched `dev` as a regular expression, and mosquitto_ctrl exits 0 for a client it
    // doesn't find: the broker started. Names are a-z, 0-9 and -, matched exactly.
    for (const extra of ['d.v:x', 'de*:x', 'dev2:x']) {
      await expect(
        startBroker({ mqttUsers: `${mqttUsers()} ${extra}`, readyTimeoutMs: 3_000 }),
        extra,
      ).rejects.toThrow(/did not start/);
    }
  });

  it('refuses an empty password (security review F3)', async () => {
    const users = mqttUsers().replace(/\bdev:\S+/, 'dev:');
    expect(users).toMatch(/(^| )dev:( |$)/);
    await expect(startBroker({ mqttUsers: users, readyTimeoutMs: 3_000 })).rejects.toThrow(
      /did not start/,
    );
  });

  it('starts Mosquitto without the passwords in its environment (security review F4)', async () => {
    const { output } = await current.container.exec([
      'sh',
      '-c',
      'tr "\\0" "\\n" </proc/1/environ',
    ]);
    expect(output).not.toMatch(/MQTT_USERS/);
    expect(output).not.toContain(TEST_PASSWORDS['gw-01']);
  });

  it('keeps the generated configuration (password hashes) private to the broker', async () => {
    const { output } = await current.container.exec([
      'stat',
      '-c',
      '%a %U',
      '/mosquitto/data/dynamic-security.json',
    ]);
    expect(output.trim()).toBe('600 mosquitto');
    const passwd = await current.container.exec(['test', '-e', '/mosquitto/data/passwd']);
    expect(passwd.exitCode).not.toBe(0);
  });
});

// Regressions from the security review of PR #261 (F6) --------------------------------------------

/** QoS 1 publish outcome: 'allowed' or 'refused' (PUBACK 0x87). */
const publishResult = (c: MqttClient, topic: string, payload: string, retain = false) =>
  c.publishAsync(topic, payload, { qos: 1, retain }).then(
    () => 'allowed',
    (error: unknown) => (String(error).includes('Not authorized') ? 'refused' : String(error)),
  );

describe('regressions (security review of PR #261)', () => {
  it('refuses $CONTROL/dynamic-security/v1 to every user, createClient included', async () => {
    const command = JSON.stringify({
      commands: [
        { command: 'createClient', username: 'intruder', password: 'intruder-pw', roles: [] },
        { command: 'setDefaultACLAccess', acls: [{ acltype: 'publishClientSend', allow: true }] },
      ],
    });
    for (const user of Object.keys(TEST_PASSWORDS) as BrokerUser[]) {
      const c = await connect(current.url, brokerLogin(user));
      expect(await publishResult(c, '$CONTROL/dynamic-security/v1', command), user).toBe('refused');
      await c.endAsync();
    }
    expect(
      await refusal(current.url, {
        username: 'intruder',
        password: 'intruder-pw',
        clientId: 'intruder',
      }),
    ).toMatch(/Not authorized|Bad User Name or Password/);
    // And the default access is unchanged: dev still may not publish.
    const dev = await connect(current.url, brokerLogin('dev'));
    expect(await publishResult(dev, 'orbis/gebze/machining/cell-m1/cnc-01/state/x', '{}')).toBe(
      'refused',
    );
  });

  it('never delivers a will on a topic its user may not publish', async () => {
    const topic = 'orbis/gebze/machining/cell-m1/cnc-01/state/current';
    const reader = await connect(current.url, brokerLogin('mes-cmd'));
    const got: string[] = [];
    reader.on('message', (t) => got.push(t));
    await reader.subscribeAsync('orbis/#', { qos: 1 });
    for (const user of ['dev', 'smoke-reader', 'mes'] as const) {
      const outcome = await mqtt
        .connectAsync(current.url, {
          ...brokerLogin(user),
          protocolVersion: 5,
          reconnectPeriod: 0,
          will: { topic, payload: Buffer.from('forged'), qos: 1, retain: true },
        })
        .then(
          (c) => {
            c.stream.destroy(); // no DISCONNECT: the broker would send the will
            return 'connected';
          },
          (error: unknown) => String(error),
        );
      expect(outcome, user).toMatch(/connected|Not authorized/);
    }
    await wait(1_000);
    expect(got).toEqual([]);
  });

  it('stores no retained message published by dev or smoke-reader', async () => {
    const topic = 'orbis/gebze/machining/cell-m1/cnc-01/state/retained-probe';
    for (const user of ['dev', 'smoke-reader'] as const) {
      const c = await connect(current.url, brokerLogin(user));
      expect(await publishResult(c, topic, '{"forged":true}', true), user).toBe('refused');
      await c.endAsync();
    }
    const reader = await connect(current.url, brokerLogin('mes-cmd'));
    const got: string[] = [];
    reader.on('message', (t) => got.push(t));
    await reader.subscribeAsync(topic, { qos: 1 });
    await wait(500);
    expect(got).toEqual([]);
  });

  it('refuses an empty client id (MQTT 5, broker-assigned) for every user', async () => {
    for (const user of Object.keys(TEST_PASSWORDS) as BrokerUser[]) {
      expect(
        await refusal(current.url, { ...brokerLogin(user), clientId: '', clean: true }),
        user,
      ).toMatch(/Not authorized/);
    }
  });
});

// ACL parity -------------------------------------------------------------------------------------

/** The Phase 8 ACL's users, and which current users stand for each (same role). */
const PARITY_USERS: Readonly<Record<string, readonly BrokerUser[]>> = {
  healthcheck: ['healthcheck'],
  dev: ['dev', 'smoke-reader'],
  'gw-01': ['gw-01', 'gw-01-cmd'],
  mes: ['mes', 'mes-cmd'],
};

const M = 'orbis/gebze/machining/cell-m1/cnc-01';
const A = 'orbis/gebze/assembly/cell-a1/asm-01';
const S = 'orbis/gebze/_sys';

/** Publish (QoS 1): the topics, and which Phase 8 users may write each. */
const PUBLISH: readonly (readonly [string, readonly string[]])[] = [
  [`${M}/state/current`, ['gw-01']],
  [`${M}/telemetry/spindle-load`, ['gw-01']],
  [`${M}/events/cycle`, ['gw-01']],
  [`${M}/alarms/a-1`, ['gw-01']],
  [`${M}/cmd/load-order`, ['mes']],
  [`${M}/cmd-res/load-order`, ['gw-01']],
  [`${M}/mes/active-order`, ['mes']],
  [`${A}/state/current`, ['gw-01']],
  [`${A}/telemetry/torque`, ['gw-01']],
  [`${A}/events/cycle`, ['gw-01']],
  [`${A}/alarms/a-1`, ['gw-01']],
  [`${A}/cmd/load-program`, ['mes']],
  [`${A}/cmd-res/load-program`, ['gw-01']],
  [`${A}/mes/active-order`, ['mes']],
  [`${S}/edge-gateway/gw-01/status`, ['gw-01']],
  [`${S}/edge-gateway/gw-02/status`, []],
  [`${S}/mes-server/main/state/x`, ['mes']],
  // `+` in the area position must not reach _sys: no user writes these.
  [`${S}/cell/eq/state/current`, []],
  [`${S}/cell/eq/cmd/x`, []],
  // An area the ACL doesn't list, and topics outside the UNS.
  ['orbis/gebze/quality/cell-q1/cmm-01/state/current', []],
  ['orbis/other', []],
  ['smoke/anon', []],
  ['$SYS/broker/uptime', []],
];

/**
 * Subscribe: the filters, and which Phase 8 users may subscribe to each. Mosquitto 2.1's ACL file
 * grants every subscription and checks each message on delivery (`topic read`), so every user may
 * subscribe to every filter, `#` included; what reaches it is the delivery test's table. The
 * dynamic-security template keeps that (default `subscribe: true`, `publishClientReceive` per
 * role).
 */
const EVERYONE = ['healthcheck', 'dev', 'gw-01', 'mes'];
const SUBSCRIBE: readonly (readonly [string, readonly string[]])[] = [
  'orbis/#',
  'orbis/gebze/+/+/+/state/current',
  `${M}/state/current`,
  'orbis/gebze/machining/+/+/cmd/#',
  'orbis/gebze/assembly/+/+/cmd/#',
  `${M}/cmd/load-order`,
  'orbis/gebze/+/+/+/cmd/#',
  'orbis/gebze/machining/+/+/cmd-res/#',
  'orbis/gebze/machining/+/+/state/#',
  `${S}/edge-gateway/gw-01/#`,
  `${S}/edge-gateway/gw-02/#`,
  `${S}/mes-server/#`,
  `${S}/#`,
  '$SYS/#',
  '$SYS/broker/uptime',
  '#',
  '+/gebze/#',
  'smoke/#',
].map((filter) => [filter, EVERYONE] as const);

/** The PUBACK of a QoS 1 publish: 'allowed' (any success code) or 'refused' (0x87). */
async function publishOutcome(c: MqttClient, topic: string): Promise<string> {
  try {
    await c.publishAsync(topic, '{}', { qos: 1 });
    return 'allowed';
  } catch (error) {
    const code = (error as { code?: number }).code;
    if (code === 0x87 || String(error).includes('Not authorized')) return 'refused';
    return `error: ${String(error)}`;
  }
}

/** The SUBACK of one subscription: 'allowed' (QoS granted) or 'refused' (0x87). */
async function subscribeOutcome(c: MqttClient, filter: string): Promise<string> {
  // MQTT.js rejects a subscription the broker refused (SUBACK reason 0x87).
  const granted = await c.subscribeAsync(filter, { qos: 1 }).then(
    ([grant]) => grant?.qos as number | undefined,
    (error: unknown) => (String(error).includes('Not authorized') ? 0x87 : String(error)),
  );
  const outcome =
    granted === 0x87 ? 'refused' : granted === 1 ? 'allowed' : `code ${String(granted)}`;
  if (outcome === 'allowed') await c.unsubscribeAsync(filter);
  return outcome;
}

/** The users of one broker, connected with their bound (or any) client id. */
async function connectAll(
  url: string,
  users: readonly BrokerUser[],
): Promise<Map<string, MqttClient>> {
  const clients = new Map<string, MqttClient>();
  for (const user of users) clients.set(user, await connect(url, brokerLogin(user)));
  return clients;
}

describe('ACL parity with the Phase 8 ACL file (S2)', () => {
  it('publishes: every (user, topic) allowed or refused exactly as before', async () => {
    const legacyClients = await connectAll(legacy.url, Object.keys(PARITY_USERS) as BrokerUser[]);
    const currentClients = await connectAll(current.url, Object.values(PARITY_USERS).flat());
    for (const [topic, writers] of PUBLISH) {
      for (const [legacyUser, currentUsers] of Object.entries(PARITY_USERS)) {
        const expected = writers.includes(legacyUser) ? 'allowed' : 'refused';
        const legacyClient = legacyClients.get(legacyUser);
        if (!legacyClient) throw new Error(legacyUser);
        expect(await publishOutcome(legacyClient, topic), `Phase 8 ${legacyUser} → ${topic}`).toBe(
          expected,
        );
        for (const user of currentUsers) {
          const c = currentClients.get(user);
          if (!c) throw new Error(user);
          expect(await publishOutcome(c, topic), `${user} → ${topic}`).toBe(expected);
        }
      }
    }
  });

  it('subscribes: every (user, filter) allowed or refused exactly as before', async () => {
    const legacyClients = await connectAll(legacy.url, Object.keys(PARITY_USERS) as BrokerUser[]);
    const currentClients = await connectAll(current.url, Object.values(PARITY_USERS).flat());
    for (const [filter, readers] of SUBSCRIBE) {
      for (const [legacyUser, currentUsers] of Object.entries(PARITY_USERS)) {
        const expected = readers.includes(legacyUser) ? 'allowed' : 'refused';
        const legacyClient = legacyClients.get(legacyUser);
        if (!legacyClient) throw new Error(legacyUser);
        expect(
          await subscribeOutcome(legacyClient, filter),
          `Phase 8 ${legacyUser} ⊂ ${filter}`,
        ).toBe(expected);
        for (const user of currentUsers) {
          const c = currentClients.get(user);
          if (!c) throw new Error(user);
          expect(await subscribeOutcome(c, filter), `${user} ⊂ ${filter}`).toBe(expected);
        }
      }
    }
  });

  it('delivers: each user receives exactly the messages it received before', async () => {
    // Each reader subscribes to every filter it may; the writers then publish every writable
    // topic once. What each reader receives (the read check on delivery, not only the subscribe
    // check) must match the Phase 8 broker's deliveries. The writers hold the bound ids gw-01 and
    // mes-server, so on the current broker the component readers are the second users
    // (gw-01-cmd, mes-cmd, same roles); on the Phase 8 broker, gw-01 and mes under other ids.
    const writable = PUBLISH.filter(([, writers]) => writers.length > 0);
    const deliveries = async (
      url: string,
      readers: Readonly<Record<string, IClientOptions>>,
    ): Promise<Record<string, string[]>> => {
      const got: Record<string, Set<string>> = {};
      for (const [label, options] of Object.entries(readers)) {
        const c = await connect(url, options);
        const topics = new Set<string>();
        got[label] = topics;
        c.on('message', (topic) => {
          if (!topic.startsWith('$SYS')) topics.add(topic);
        });
        for (const [filter] of SUBSCRIBE) await c.subscribeAsync(filter, { qos: 1 });
      }
      const writers = {
        'gw-01': await connect(url, brokerLogin('gw-01')),
        mes: await connect(url, brokerLogin('mes')),
      };
      for (const [topic, allowed] of writable) {
        await writers[allowed[0] as 'gw-01' | 'mes'].publishAsync(topic, '{}', { qos: 1 });
      }
      await wait(500);
      return Object.fromEntries(Object.entries(got).map(([label, t]) => [label, [...t].sort()]));
    };
    const before = await deliveries(legacy.url, {
      healthcheck: brokerLogin('healthcheck'),
      dev: brokerLogin('dev'),
      'gw-01': { ...brokerLogin('gw-01'), clientId: 'gw-01-reader' },
      mes: { ...brokerLogin('mes'), clientId: 'mes-reader' },
    });
    const after = await deliveries(current.url, {
      healthcheck: brokerLogin('healthcheck'),
      dev: brokerLogin('dev'),
      'gw-01': brokerLogin('gw-01-cmd'),
      mes: brokerLogin('mes-cmd'),
    });
    expect(after).toEqual(before);
    const all = writable.map(([t]) => t).sort();
    expect(before).toEqual({
      healthcheck: [],
      dev: all,
      'gw-01': [
        `${A}/cmd/load-program`,
        `${M}/cmd/load-order`,
        `${S}/edge-gateway/gw-01/status`,
      ].sort(),
      mes: all,
    });
  });

  it('unsubscribes: always allowed, as before', async () => {
    for (const [url, users] of [
      [legacy.url, Object.keys(PARITY_USERS)],
      [current.url, Object.values(PARITY_USERS).flat()],
    ] as const) {
      const clients = await connectAll(url, users as BrokerUser[]);
      for (const [user, c] of clients) {
        const packet = await c.unsubscribeAsync('orbis/#');
        const reason = (packet as { reasonCode?: number; reasonCodes?: number[] } | undefined)
          ?.reasonCodes?.[0];
        expect(reason === undefined || reason < 0x80, `${url} ${user}`).toBe(true);
      }
    }
  });
});
